import { notFound } from 'next/navigation';

/* SHELSEA_VENDOR_EDIT_VARIANT_COLOR_V1 */

import { AdminPage, AdminPageHeader } from '@/features/admin/components';
import { getVendorAccess } from '@/features/vendor/auth/vendorAccess';
import { updateVendorProduct, VendorProductEditor } from '@/features/vendor/products';
import { prisma } from '@/lib/prisma';

export default async function EditVendorProductPage({params}:{params:Promise<{id:string}>}){const access=await getVendorAccess();if(!access.permissions.has('product:manage'))throw new Error('Product management permission is required.');const{id}=await params;const [product,categories,brands,media]=await Promise.all([prisma.product.findFirst({where:{id,workspaceId:access.workspace.id,vendorProfileId:access.vendor.id},include:{images:{orderBy:{position:'asc'}},variants:{orderBy:{position:'asc'},include:{inventory:true}}}}),prisma.category.findMany({where:{active:true},include:{subcategories:{where:{active:true},orderBy:{position:'asc'}}},orderBy:{position:'asc'}}),prisma.brand.findMany({where:{active:true},orderBy:{name:'asc'}}),prisma.mediaAsset.findMany({where:{workspaceId:access.workspace.id,vendorProfileId:access.vendor.id,status:'ACTIVE',resourceType:'IMAGE'},orderBy:{createdAt:'desc'},take:200})]);if(!product)notFound();const action=updateVendorProduct.bind(null,product.id);return <AdminPage><div className="mx-auto max-w-[96rem] space-y-5"><AdminPageHeader eyebrow={product.status.replaceAll('_',' ')} title={`Edit ${product.name}`} description="Published product edits return to the approval queue before becoming public." backHref="/vendor/products" backLabel="Vendor products"/><VendorProductEditor action={action} product={{id:product.id,name:product.name,slug:product.slug,shortDescription:product.shortDescription,longDescription:product.longDescription,categoryId:product.categoryId,subcategoryId:product.subcategoryId,brandId:product.brandId,tags:product.tags,isNew:product.isNew,estimatedDelivery:product.estimatedDelivery,discountPercentage:product.discountPercentage,status:product.status,images:product.images.map(image=>({mediaAssetId:image.mediaAssetId})),variants:product.variants.map(variant=>({id:variant.id,label:variant.label,color:variant.color??'',colorHex:variant.colorHex??'',sku:variant.sku??'',price:Number(variant.price),compareAtPrice:variant.compareAtPrice===null?null:Number(variant.compareAtPrice),mediaAssetId:variant.mediaAssetId,quantity:variant.inventory?.quantity??0,reserved:variant.inventory?.reserved??0,reorderLevel:variant.inventory?.reorderLevel??5,active:variant.active}))}} media={media.map(item=>({id:item.id,secureUrl:item.secureUrl,displayName:item.displayName,originalFilename:item.originalFilename}))} taxonomy={{categories:categories.map(item=>({id:item.id,label:item.label,subcategories:item.subcategories.map(sub=>({id:sub.id,label:sub.label}))})),brands:brands.map(item=>({id:item.id,name:item.name}))}}/></div></AdminPage>}
